const chinese = Object.fromEntries(Object.entries(english).map(([zh, en]) => [en, zh]));
export function builtinText(text, language) { return (language === 'en' ? english : chinese)[text] ?? text; }
export function localizeBuiltinTemplate(template, language) {
    if (!['builtin-feature', 'builtin-bugfix', 'builtin-operator'].includes(template.id) || !(template.version === 1 || template.id === 'builtin-feature' && template.version === 2))
        return template;
    const visit = (value) => typeof value === 'string' ? builtinText(value, language) : Array.isArray(value) ? value.map(visit) : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, visit(item)])) : value;
    return visit(template);
}
